#
# Creates (or empties and reloads) the memory repository "bsbm" used by the design review and by
# .agent/execplans/workbench-app-shell-and-critique-fixes-20260930.md, and loads two graphs.
# Usage (from the repository root): design/workbench-app-shell-plan-20260930/seed-review-repository.sh [serverBaseUrl]
set -euo pipefail

SERVER="${1:-http://127.0.0.1:18090/rdf4j-server}"
ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
REPO="${SERVER}/repositories/bsbm"

status=$(curl -s -o /dev/null -w '%{http_code}' -X PUT -H 'Content-Type: text/turtle' --data-binary @- "${REPO}" <<'TTL'
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix config: <tag:rdf4j.org,2023:config/> .
[] a config:Repository ;
   config:rep.id "bsbm" ;
   rdfs:label "BSBM demo (memory)" ;
   config:rep.impl [
      config:rep.type "openrdf:SailRepository" ;
      config:sail.impl [ config:sail.type "openrdf:MemoryStore" ]
   ] .
TTL
)
case "${status}" in
	200 | 201 | 204) echo "created repository bsbm" ;;
	409) echo "repository bsbm exists; clearing its statements"; curl -sf -X DELETE "${REPO}/statements" ;;
	*) echo "creating repository bsbm failed with HTTP ${status}" >&2; exit 1 ;;
esac
curl -sf -X POST -H 'Content-Type: text/turtle' \
	--data-binary @"${ROOT}/testsuites/sparql/src/main/resources/testcases-sparql-1.1/bsbm/bsbm-100.ttl" \
	"${REPO}/statements?context=%3Chttp://example.org/graph/bsbm%3E"
curl -sf -X POST -H 'Content-Type: text/turtle' \
	--data-binary @"${ROOT}/core/spin/src/main/resources/schema/spl.spin.ttl" \
	"${REPO}/statements?context=%3Chttp://example.org/graph/spl%3E"
printf 'bsbm size: %s statements\n' "$(curl -sf "${REPO}/size")"
